/* ARPACK dnaupd typical signature (Fortran, all pointers, hidden string lengths at end):
void dnaupd(int *ido, char *bmat, int *n, char *which, int *nev, double *tol,
            double *resid, int *ncv, double *v, int *ldv, int *iparam, int *ipntr,
            double *workd, double *workl, int *lworkl, int *info,
            int bmat_len, int which_len);
*/

typedef void (*dnaupd_fn)(int*, char*, int*, char*, int*, double*, double*, int*,
                          double*, int*, int*, int*, double*, double*, int*, int*,
                          /* hidden */ long, long);

int main(int argc, char **argv) {
    const char *path = argv[1];
    void *h = dlopen(path, RTLD_NOW);
    if (!h) { fprintf(stderr, "dlopen: %s\n", dlerror()); return 1; }
    void *sym = dlsym(h, "ARNAUD_dnaupd");
    printf("sym %p\n", sym);
    if (!sym) { fprintf(stderr, "dlsym: %s\n", dlerror()); return 1; }

    int n = 10, nev = 2, ncv = 6;
    int ido = 0, info = 0;
    char bmat = 'I';
    char which[2] = {'L','M'};
