    double *resid = calloc(n, sizeof(double));
    double *v = calloc(n * ncv, sizeof(double));
    int ldv = n;
    int iparam[11] = {0};
    iparam[0] = 1;      /* ishift */
    iparam[2] = 300;    /* maxiter */
    iparam[3] = 1;      /* NB */
    iparam[6] = 1;      /* mode */
    int ipntr[14] = {0};
    double *workd = calloc(3*n, sizeof(double));
    int lworkl = 3*ncv*(ncv+2);
    double *workl = calloc(lworkl, sizeof(double));

    dnaupd_fn fn = (dnaupd_fn)sym;
    printf("calling...\n");
    fn(&ido, &bmat, &n, which, &nev, &tol, resid, &ncv, v, &ldv,
       iparam, ipntr, workd, workl, &lworkl, &info, 1, 2);
    printf("ido=%d info=%d ipntr0=%d ipntr1=%d\n", ido, info, ipntr[0], ipntr[1]);
    printf("iparam: ");
    for (int i=0;i<11;i++) printf("%d ", iparam[i]);
    printf("\n");
