#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <string.h>
#include <dlfcn.h>
#include <stdlib.h>

typedef void (*dnaupd_fn)(
    int *ido, char *bmat, int *n, char *which, int *nev, double *tol,
    double *resid, int *ncv, double *v, int *ldv, int *iparam, int *ipntr,
    double *workd, double *workl, int *lworkl, int *info);

typedef void (*dneupd_fn)(
    int *rvec, char *howmny, int *select, double *dr, double *di,
    double *z, int *ldz, double *sigmar, double *sigmai, double *workev,
    char *bmat, int *n, char *which, int *nev, double *tol, double *resid,
    int *ncv, double *v, int *ldv, int *iparam, int *ipntr, double *workd,
    double *workl, int *lworkl, int *info);

static dnaupd_fn dnaupd = NULL;
static dneupd_fn dneupd = NULL;

static int load_arpack(void) {
    if (dnaupd) return 0;
    /* The symbols live in the already-loaded _arpacklib bundle. */
    void *h = dlopen(
        NULL, /* won't see bundle symbols */
        RTLD_NOW);
    (void)h;
    /* Find via the imported module's file and RTLD_NOLOAD after python imported it. */
    PyObject *mod = PyImport_ImportModule("scipy.sparse.linalg._eigen.arpack._arpacklib");
    if (!mod) return -1;
    PyObject *file = PyObject_GetAttrString(mod, "__file__");
    if (!file) { Py_DECREF(mod); return -1; }
    const char *path = PyUnicode_AsUTF8(file);
    void *lib = dlopen(path, RTLD_NOW | RTLD_GLOBAL);
    Py_DECREF(file);
    Py_DECREF(mod);
    if (!lib) {
        PyErr_SetString(PyExc_RuntimeError, dlerror());
        return -1;
    }
    dnaupd = (dnaupd_fn)dlsym(lib, "ARNAUD_dnaupd");
    dneupd = (dneupd_fn)dlsym(lib, "ARNAUD_dneupd");
    if (!dnaupd || !dneupd) {
        PyErr_SetString(PyExc_RuntimeError, "symbols not found");
        return -1;
    }
    return 0;
}

static void csr_matvec(int n, const int *indptr, const int *indices,
                       const double *data, const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        int a = indptr[i];
        int b = indptr[i + 1];
        for (int j = a; j < b; j++) {
            s += data[j] * x[indices[j]];
        }
        y[i] = s;
    }
}

/* solve(indptr, indices, data, k, ncv, tol, maxiter) -> (evals_complex, evecs_complex) */
static PyObject *solve(PyObject *self, PyObject *args) {
    PyObject *indptr_o, *indices_o, *data_o;
    int k = 5, ncv = 20, maxiter = 0;
    double tol = 0.0;
    if (!PyArg_ParseTuple(args, "OOO|iidi", &indptr_o, &indices_o, &data_o,
                          &k, &ncv, &tol, &maxiter))
        return NULL;
    if (load_arpack() < 0) return NULL;

    Py_buffer indptr_b, indices_b, data_b;
    if (PyObject_GetBuffer(indptr_o, &indptr_b, PyBUF_SIMPLE) < 0) return NULL;
    if (PyObject_GetBuffer(indices_o, &indices_b, PyBUF_SIMPLE) < 0) { PyBuffer_Release(&indptr_b); return NULL; }
    if (PyObject_GetBuffer(data_o, &data_b, PyBUF_SIMPLE) < 0) {
        PyBuffer_Release(&indices_b); PyBuffer_Release(&indptr_b); return NULL;
    }
    int n = (int)(indptr_b.len / sizeof(int)) - 1;
    const int *indptr = (const int *)indptr_b.buf;
    const int *indices = (const int *)indices_b.buf;
    const double *data = (const double *)data_b.buf;

    if (maxiter <= 0) maxiter = n * 200;
    if (ncv < k + 2) ncv = k + 2;

    int ido = 0, info = 1; /* info=1: use resid as starting vector */
    char bmat = 'I';
    char which[2] = {'L', 'M'};
    double *resid = (double *)calloc(n, sizeof(double));
    for (int i = 0; i < n; i++) resid[i] = 1.0;
    double *v = (double *)calloc((size_t)n * ncv, sizeof(double));
    int ldv = n;
    int iparam[11];
    memset(iparam, 0, sizeof(iparam));
    iparam[0] = 1;       /* ishift = 1 */
    iparam[2] = maxiter;
    iparam[3] = 1;       /* NB */
    iparam[6] = 1;       /* mode */
    int ipntr[14];
    memset(ipntr, 0, sizeof(ipntr));
    double *workd = (double *)calloc(3 * n, sizeof(double));
    int lworkl = 3 * ncv * (ncv + 2);
    double *workl = (double *)calloc(lworkl, sizeof(double));

    int iter_guard = 0;
    int max_calls = maxiter * ncv * 4 + 1000;
    while (iter_guard++ < max_calls) {
        dnaupd(&ido, &bmat, &n, which, &k, &tol, resid, &ncv, v, &ldv,
               iparam, ipntr, workd, workl, &lworkl, &info);
        if (ido == 1 || ido == -1 || ido == 5) {
            /* y = A x ; pointers are 1-based */
            int xoff = ipntr[0] - 1;
            int yoff = ipntr[1] - 1;
            csr_matvec(n, indptr, indices, data, workd + xoff, workd + yoff);
        } else if (ido == 2) {
            int xoff = ipntr[0] - 1;
            int yoff = ipntr[1] - 1;
            memcpy(workd + yoff, workd + xoff, n * sizeof(double));
        } else if (ido == 4) {
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else {
            break;
        }
    }
    int naupd_info = info;
    int nconv = iparam[4];

    /* extract */
    int rvec = 1;
    char howmny = 'A';
    int *select = (int *)calloc(ncv, sizeof(int));
    double *dr = (double *)calloc(k + 1, sizeof(double));
    double *di = (double *)calloc(k + 1, sizeof(double));
    double *z = (double *)calloc((size_t)n * (k + 1), sizeof(double));
    int ldz = n;
    double sigmar = 0.0, sigmai = 0.0;
    double *workev = (double *)calloc(3 * ncv, sizeof(double));
    info = 0;
    dneupd(&rvec, &howmny, select, dr, di, z, &ldz, &sigmar, &sigmai, workev,
           &bmat, &n, which, &k, &tol, resid, &ncv, v, &ldv, iparam, ipntr,
           workd, workl, &lworkl, &info);
    int neupd_info = info;
    nconv = iparam[4];

    /* Build complex eigenvalues/vectors the same way scipy does. */
    int nret = nconv;
    if (nret > k + 1) nret = k + 1;
    /* complex pair assembly into k+1 slots */
    double *cr = (double *)calloc(k + 1, sizeof(double));
    double *ci = (double *)calloc(k + 1, sizeof(double));
    double *zr = (double *)calloc((size_t)n * (k + 1), sizeof(double));
    double *zi = (double *)calloc((size_t)n * (k + 1), sizeof(double));
    for (int i = 0; i < k + 1; i++) { cr[i] = dr[i]; ci[i] = di[i]; }
    int i = 0;
    while (i <= k) {
        if (di[i] != 0.0) {
            if (i < k) {
                for (int r = 0; r < n; r++) {
                    zr[r + n * i] = z[r + n * i];
                    zi[r + n * i] = z[r + n * (i + 1)];
                    zr[r + n * (i + 1)] = z[r + n * i];
                    zi[r + n * (i + 1)] = -z[r + n * (i + 1)];
                }
                i += 1;
            } else {
                nret -= 1;
            }
        } else {
            for (int r = 0; r < n; r++) {
                zr[r + n * i] = z[r + n * i];
                zi[r + n * i] = 0.0;
            }
        }
        i += 1;
    }

    int nout = nret < k ? nret : k;
    /* select k largest modulus among available (up to k+1) */
    int avail = nret;
    if (avail > k + 1) avail = k + 1;
    double *mag = (double *)calloc(avail, sizeof(double));
    int *order = (int *)calloc(avail, sizeof(int));
    for (int j = 0; j < avail; j++) {
        mag[j] = cr[j] * cr[j] + ci[j] * ci[j];
        order[j] = j;
    }
    /* simple sort descending */
    for (int a = 0; a < avail; a++) {
        for (int b = a + 1; b < avail; b++) {
            if (mag[order[b]] > mag[order[a]]) {
                int tmp = order[a]; order[a] = order[b]; order[b] = tmp;
            }
        }
    }
    if (nout > avail) nout = avail;

    npy_load(); /* placeholder to fail compile if I forget numpy — we'll return lists instead */

    PyObject *list = PyList_New(nout);
    for (int t = 0; t < nout; t++) {
        int j = order[t];
        PyObject *vec = PyList_New(n);
        for (int r = 0; r < n; r++) {
            Py_complex c;
            c.real = zr[r + n * j];
            c.imag = zi[r + n * j];
            PyList_SET_ITEM(vec, r, PyComplex_FromCComplex(c));
        }
        PyList_SET_ITEM(list, t, vec);
    }

    PyBuffer_Release(&data_b);
    PyBuffer_Release(&indices_b);
    PyBuffer_Release(&indptr_b);
    free(resid); free(v); free(workd); free(workl);
    free(select); free(dr); free(di); free(z); free(workev);
    free(cr); free(ci); free(zr); free(zi); free(mag); free(order);

    PyObject *info_t = Py_BuildValue("iii", naupd_info, neupd_info, nconv);
    return Py_BuildValue("OO", list, info_t);
}

