#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <dlfcn.h>
#include <mach/mach_vm.h>
#include <mach/mach_init.h>
#include <libkern/OSCacheControl.h>

/* Interpose: patch the call inside dnaupd_wrap to jump to our logger, which
   dumps the first 8 register args and the stack, then jumps to the real function.
   Easier: replace the first bytes of ARNAUD_dnaupd with a trampoline. */

typedef void (*fn_t)();

static uint8_t saved[16];
static void *real_addr;
static uint8_t *trampoline;

static void log_call(void) {
    /* This is called with the original register state? No, if we use a
       C function we clobber. Use inline asm trampoline instead. */
}

/* We'll build an assembly trampoline that saves regs, calls logger, restores, jumps. */
extern void logger(uint64_t rdi, uint64_t rsi, uint64_t rdx, uint64_t rcx,
                   uint64_t r8, uint64_t r9, uint64_t *stack);

void logger(uint64_t rdi, uint64_t rsi, uint64_t rdx, uint64_t rcx,
            uint64_t r8, uint64_t r9, uint64_t *stack) {
    fprintf(stderr, "CALL rdi=%llx rsi=%llx rdx=%llx rcx=%llx r8=%llx r9=%llx\n",
            rdi, rsi, rdx, rcx, r8, r9);
    fprintf(stderr, "  stack[0]=%llx (ret)\n", stack[0]);
    for (int i = 1; i <= 12; i++) {
        fprintf(stderr, "  stack[%d]=%llx\n", i, stack[i]);
    }
    if (rdi) fprintf(stderr, "  *ido=%d\n", *(int*)rdi);
    if (rsi) fprintf(stderr, "  bmat=%.2s\n", (char*)rsi);
    if (rdx) fprintf(stderr, "  *n=%d\n", *(int*)rdx);
    if (rcx) fprintf(stderr, "  which=%.2s\n", (char*)rcx);
    fflush(stderr);
}

/* trampoline machine code:
   push all caller-saved? We need to not disturb args.
   We'll write:
     push %rbp
     mov %rsp, %rbp
     # stack layout after call to logger needs the original stack pointer
