    uint8_t *call_site = (uint8_t *)(base + 0x11e0 + 0x150);
    fprintf(stderr, "call_site %p bytes %02x %02x\n", call_site, call_site[0], call_site[1]);

    uint8_t *tramp = mmap(NULL, 4096, PROT_READ|PROT_WRITE|PROT_EXEC, MAP_PRIVATE|MAP_ANON, -1, 0);

    /* At call_site, a call instruction pushes ret and jumps. We replace the e8 rel32
       (5 bytes) with e9 rel32 (jmp to tramp). Tramp must simulate the call. */
    uint8_t *p = tramp;
    /* The jmp from call_site does NOT push a return address. We need to call dump
       then jump to dnaupd, and dnaupd must return to call_site+5.
       So: push <call_site+5>, then set up and call dump? dump needs the arg regs
       which are already set, plus rsp. But push changes rsp.
       Sequence:
         ; regs intact, rsp as it was at the call instruction (before push)
         ; We want dump to see rsp as dnaupd would (after the call push).
         push <retaddr = call_site+5>     ; now rsp is what dnaupd sees, [rsp]=ret
         ; save regs, align, call dump(rdi..r9, rsp_after_push)
    */
    /* We'll hardcode retaddr. */
    uint8_t pre[] = {
        0x68, 0, 0, 0, 0,       /* push imm32 retaddr low — only works if retaddr fits in 32-bit sign. It doesn't (high address). */
    };
    (void)pre;
    /* use mov rax; push rax but that clobbers rax. Save rax first. */
    /* push rax
       mov rax, retaddr
       xchg rax, [rsp]      ; [rsp]=retaddr, rax restored? xchg rax,[rsp] puts old rax back. YES.
       ; now stack has retaddr, rax original. But we used a slot. rsp is correct for dnaupd.
    */
    p[0] = 0x50; p++;                         /* push rax */
    p[0] = 0x48; p[1] = 0xb8; p += 2;         /* mov rax, imm64 */
    uint64_t retaddr = (uint64_t)(call_site + 5);
    memcpy(p, &retaddr, 8); p += 8;
    uint8_t xchg[] = {0x48, 0x87, 0x04, 0x24}; /* xchg rax, [rsp] */
    memcpy(p, xchg, 4); p += 4;
    /* now [rsp]=retaddr, rax=original. Save volatile regs and call dump. */
    uint8_t save[] = {
        0x50,             /* push rax (original) */
        0x51,             /* push rcx */
        0x52,             /* push rdx */
        0x56,             /* push rsi */
        0x57,             /* push rdi */
        0x41, 0x50,       /* push r8 */
        0x41, 0x51,       /* push r9 */
        0x41, 0x52,       /* push r10 */
        0x41, 0x53,       /* push r11 */
        /* 9 pushes. entry-to-this-point rsp was already 8-mod-16 (because we pushed retaddr).
           9 more -> rsp%16 == 8+8 = 0. Need 8 before call, so sub 8. */
        0x48, 0x83, 0xec, 0x08,
        0x48, 0x89, 0xe0,             /* mov rax, rsp */
        0x48, 0x83, 0xc0, 0x50,       /* add rax, 80 ; points at retaddr slot */
        0x48, 0x89, 0x04, 0x24,       /* mov [rsp], rax  ; 7th arg */
        0x48, 0xb8                    /* mov rax, dump */
    };
    memcpy(p, save, sizeof(save)); p += sizeof(save);
    uint64_t daddr = (uint64_t)(uintptr_t)dump;
    memcpy(p, &daddr, 8); p += 8;
    uint8_t rest[] = {
        0xff, 0xd0,                   /* call rax */
        0x48, 0x83, 0xc4, 0x08,
        0x41, 0x5b, 0x41, 0x5a, 0x41, 0x59, 0x41, 0x58,
        0x5f, 0x5e, 0x5a, 0x59, 0x58,
        /* now [rsp]=retaddr, regs restored. jump to dnaupd (it will ret to retaddr) */
        0x48, 0xb8
    };
    memcpy(p, rest, sizeof(rest)); p += sizeof(rest);
    uint64_t target = (uint64_t)(uintptr_t)dnaupd;
    memcpy(p, &target, 8); p += 8;
    p[0] = 0xff; p[1] = 0xe0;

    /* patch call site e8 rel32 -> e9 rel32 to tramp. 5 bytes, same length. */
    uintptr_t page = (uintptr_t)call_site & ~0xFFFull;
    mprotect((void*)page, 8192, PROT_READ|PROT_WRITE|PROT_EXEC);
    int32_t rel = (int32_t)((uint8_t *)tramp - (call_site + 5));
    call_site[0] = 0xe9;
    memcpy(call_site + 1, &rel, 4);
    fprintf(stderr, "patched jmp rel %d\n", rel);
    Py_RETURN_NONE;
}

